create extension if not exists pgcrypto;
create type public.radar_status as enum ('active','paused','running','error');
create type public.opportunity_status as enum ('new','saved','contacted','negotiating','won','lost','ignored');
create type public.opportunity_type as enum ('job','client','project','business','github');

create table public.profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, display_name text not null, identity text default '', location text default '', monthly_income_goal integer default 0, minimum_project_budget integer default 0, available_hours_per_day numeric default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.profile_skills (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, skill_name text not null, skill_level text not null check (skill_level in ('beginner','intermediate','strong','expert')), created_at timestamptz default now());
create table public.profile_goals (profile_id uuid not null references public.profiles(id) on delete cascade, goal text not null check (goal in ('job','client','project','business')), primary key(profile_id,goal));
create table public.sources (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, type text not null, status text not null default 'available', config jsonb not null default '{}'::jsonb, created_at timestamptz default now());
create table public.radars (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, description text default '', goal text not null, status public.radar_status not null default 'active', minimum_budget integer default 0, currency text default 'CNY', frequency text default 'daily', freshness_hours integer default 72, last_run_at timestamptz, next_run_at timestamptz, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.radar_keywords (id uuid primary key default gen_random_uuid(), radar_id uuid not null references public.radars(id) on delete cascade, keyword text not null);
create table public.radar_locations (id uuid primary key default gen_random_uuid(), radar_id uuid not null references public.radars(id) on delete cascade, location text not null);
create table public.radar_sources (radar_id uuid not null references public.radars(id) on delete cascade, source_id uuid not null references public.sources(id), enabled boolean not null default true, primary key(radar_id,source_id));
create table public.radar_queries (id uuid primary key default gen_random_uuid(), radar_id uuid not null references public.radars(id) on delete cascade, query text not null, source text not null, priority integer not null, created_at timestamptz default now(), last_run_at timestamptz, enabled boolean not null default true);
create table public.radar_runs (id uuid primary key default gen_random_uuid(), radar_id uuid not null references public.radars(id) on delete cascade, status text not null, started_at timestamptz default now(), finished_at timestamptz, query_count integer default 0, items_found integer default 0, items_deduplicated integer default 0, items_analyzed integer default 0, opportunities_found integer default 0, matched_count integer default 0, recommended_count integer default 0, error_message text);
create table public.raw_items (id uuid primary key default gen_random_uuid(), radar_id uuid not null references public.radars(id) on delete cascade, source_id uuid references public.sources(id), external_id text, title text not null, content text not null, url text not null, author text, published_at timestamptz, captured_at timestamptz default now(), content_hash text not null, url_hash text not null, raw_data jsonb not null default '{}'::jsonb, processing_status text not null default 'pending', unique(radar_id,url_hash), unique(radar_id,content_hash));
create table public.opportunities (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, radar_id uuid not null references public.radars(id) on delete cascade, raw_item_id uuid references public.raw_items(id), type public.opportunity_type not null, title text not null, summary text not null, source text not null, source_url text not null, published_at timestamptz, location text default '', work_mode text default 'online', budget_min integer default 0, budget_max integer default 0, currency text default 'CNY', estimated_hours numeric default 0, match_score integer not null, opportunity_score integer not null, conversion_probability integer not null, risk_score integer not null, recommendation text not null, status public.opportunity_status not null default 'new', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.opportunity_analysis (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null unique references public.opportunities(id) on delete cascade, commercial_intent integer, skill_match integer, income_score integer, hourly_rate_score integer, conversion_score integer, urgency_score integer, competition_score integer, risk_score integer, reasoning_summary text, created_at timestamptz default now());
create table public.opportunity_skills (opportunity_id uuid not null references public.opportunities(id) on delete cascade, skill text not null, matched boolean not null default true, primary key(opportunity_id,skill));
create table public.opportunity_reasons (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.opportunities(id) on delete cascade, reason text not null);
create table public.opportunity_warnings (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.opportunities(id) on delete cascade, warning text not null);
create table public.opportunity_actions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, opportunity_id uuid not null references public.opportunities(id) on delete cascade, action public.opportunity_status not null, metadata jsonb not null default '{}'::jsonb, actual_revenue integer, actual_hours numeric, closed_at timestamptz, created_at timestamptz default now());
create table public.daily_briefs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, date date not null, scanned_count integer default 0, opportunities_count integer default 0, recommended_count integer default 0, potential_income_min integer default 0, potential_income_max integer default 0, summary text default '', signals jsonb default '[]'::jsonb, avoid jsonb default '[]'::jsonb, actions jsonb default '[]'::jsonb, created_at timestamptz default now(), unique(user_id,date));
create index opportunities_user_status_idx on public.opportunities(user_id,status,opportunity_score desc);
create index radars_user_idx on public.radars(user_id);

alter table public.profiles enable row level security; alter table public.profile_skills enable row level security; alter table public.profile_goals enable row level security; alter table public.radars enable row level security; alter table public.radar_keywords enable row level security; alter table public.radar_locations enable row level security; alter table public.radar_sources enable row level security; alter table public.radar_queries enable row level security; alter table public.radar_runs enable row level security; alter table public.raw_items enable row level security; alter table public.opportunities enable row level security; alter table public.opportunity_analysis enable row level security; alter table public.opportunity_skills enable row level security; alter table public.opportunity_reasons enable row level security; alter table public.opportunity_warnings enable row level security; alter table public.opportunity_actions enable row level security; alter table public.daily_briefs enable row level security; alter table public.sources enable row level security;
create policy "profile_owner" on public.profiles for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "radar_owner" on public.radars for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "opportunity_owner" on public.opportunities for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "action_owner" on public.opportunity_actions for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "brief_owner" on public.daily_briefs for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "source_read" on public.sources for select using (true);
create policy "profile_children" on public.profile_skills for all using (exists(select 1 from public.profiles p where p.id=profile_id and p.user_id=auth.uid())) with check (exists(select 1 from public.profiles p where p.id=profile_id and p.user_id=auth.uid()));
create policy "goal_children" on public.profile_goals for all using (exists(select 1 from public.profiles p where p.id=profile_id and p.user_id=auth.uid())) with check (exists(select 1 from public.profiles p where p.id=profile_id and p.user_id=auth.uid()));
create policy "radar_children" on public.radar_keywords for all using (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid())) with check (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid()));
create policy "radar_locations_owner" on public.radar_locations for all using (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid())) with check (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid()));
create policy "radar_sources_owner" on public.radar_sources for all using (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid())) with check (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid()));
create policy "radar_queries_owner" on public.radar_queries for all using (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid())) with check (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid()));
create policy "runs_owner" on public.radar_runs for all using (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid())) with check (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid()));
create policy "raw_owner" on public.raw_items for all using (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid())) with check (exists(select 1 from public.radars r where r.id=radar_id and r.user_id=auth.uid()));
create policy "analysis_owner" on public.opportunity_analysis for all using (exists(select 1 from public.opportunities o where o.id=opportunity_id and o.user_id=auth.uid())) with check (exists(select 1 from public.opportunities o where o.id=opportunity_id and o.user_id=auth.uid()));
create policy "opportunity_skills_owner" on public.opportunity_skills for all using (exists(select 1 from public.opportunities o where o.id=opportunity_id and o.user_id=auth.uid())) with check (exists(select 1 from public.opportunities o where o.id=opportunity_id and o.user_id=auth.uid()));
create policy "reasons_owner" on public.opportunity_reasons for all using (exists(select 1 from public.opportunities o where o.id=opportunity_id and o.user_id=auth.uid())) with check (exists(select 1 from public.opportunities o where o.id=opportunity_id and o.user_id=auth.uid()));
create policy "warnings_owner" on public.opportunity_warnings for all using (exists(select 1 from public.opportunities o where o.id=opportunity_id and o.user_id=auth.uid())) with check (exists(select 1 from public.opportunities o where o.id=opportunity_id and o.user_id=auth.uid()));
